import{_ as t}from"./chunks/5ff8ba290bfcde7c2f1b.eo6Ni8ts.js";import{_ as r,C as l,o,c as i,j as e,a as s,E as n,a5 as h}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"启动一人企业最简单的方法(微产品)","description":"","frontmatter":{"title":"启动一人企业最简单的方法(微产品)","originalTitle":"The Simplest Way To Start A One-Person Business (Micro Products)","date":"2024-11-23","originalUrl":"https://thedankoe.com/letters/the-simplest-way-to-start-a-one-person-business-micro-products/","minutes":13,"sourceHash":"69726a3df7280353d82d23a71d26b92b9a25e97ecc549385d545033e300dff74","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-simplest-way-to-start-a-one-person-business-micro-products/"}]]},"headers":[],"relativePath":"letters/the-simplest-way-to-start-a-one-person-business-micro-products.md","filePath":"letters/the-simplest-way-to-start-a-one-person-business-micro-products.md"}'),d={name:"letters/the-simplest-way-to-start-a-one-person-business-micro-products.md"};function m(c,p,u,_,b,f){const a=l("ArticleMeta");return o(),i("div",null,[p[0]||(p[0]=e("h1",{id:"启动一人企业最简单的方法-微产品",tabindex:"-1"},[s("启动一人企业最简单的方法(微产品) "),e("a",{class:"header-anchor",href:"#启动一人企业最简单的方法-微产品","aria-label":'Permalink to "启动一人企业最简单的方法(微产品)"'},"​")],-1)),n(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/hRgG8omhOJ0?si=_YoiCPuYIuF39Ja-" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我经常谈论如何启动一人企业。</p><p>为什么?</p><p>因为对初学者来说,这是最合乎逻辑的选择。</p><p>我是说,当你刚起步的时候,你真的期望自己能启动一个比_一人_企业_更大_的东西吗?</p><p>很多人都梦想创办像服装品牌或软件创业公司之类的东西,或是其他需要大量资本和资源才能运作的生意。</p><p>这就说得通了,为什么一人企业作为起点这么有吸引力。</p><p>你可以仅凭纯粹的技能和努力,打造出一批受众和可观的月收入。</p><p>你可以利用这些受众和收入,去启动你想做的任何其他生意,比如那个服装品牌。当你拥有一批满是潜在客户的受众,以及能覆盖初期成本和库存的收入时,创办这些生意就容易多了。</p><p>或者,你也可以就作为一个人,尽可能地把规模扩大到你想要的程度。</p><p>就像萨姆·奥特曼(Sam Altman)说的,他和朋友们有一个群聊,大家在打赌谁会是第一个做到10亿美元规模的一人企业。因为借助社交媒体和数字产品这样的现代技术,已经有不少人达到了100万美元和1000万美元的水平。</p><p>现在,我收到的关于起步的最大问题是这个:</p><p>“好吧Dan,我喜欢一人企业这个概念,但_我到底该怎么开始?”_</p><p>所以,我要为你列出最简单的路径。</p><p>我会假设你名下只有几美元,以及几个你觉得可以转化成生意的兴趣。</p><p>暂时不用担心建网站、注册LLC,甚至不用担心税务问题。如果你还没赚到至少1万到5万美元,你没事的。没人会为这么点小钱来找你麻烦(当然,在商业语境下,我知道那也是一笔不小的钱)。先把这些从脑子里清除,专注于真正开始赚钱。</p><p>最后一件事。</p><p>我不会教你如何开一家代理公司或电商店铺,或者网上能找到的其他任何东西。</p><p>我要教给你的,是网络生意最基本的骨架。</p><p>这为什么重要?</p><p>因为你可以由此成长、转向,并扩展到任何其他商业模式中去。</p><p>我们开始吧。</p><h2 id="第一步-搭建一套简单的数字工具组合" tabindex="-1">第一步)搭建一套简单的数字工具组合 <a class="header-anchor" href="#第一步-搭建一套简单的数字工具组合" aria-label="Permalink to &quot;第一步)搭建一套简单的数字工具组合&quot;">​</a></h2><p>我们在这一部分讨论的一切,_就是你的生意本身。_</p><p>这些就是你每天或每周都要登录使用的工具。</p><p>最好现在就注册并收藏它们。大多数都是免费起步的。</p><p>搭建一个网络生意,你需要四样东西:</p><ol><li><strong>一个能产生流量的地方</strong>(用来吸引潜在客户)</li><li><strong>一个能收集邮箱的地方</strong>(这样你就能直接触达感兴趣的潜在客户,并对他们进行再营销)</li><li><strong>一个能接受付款、托管你的产品或服务的地方</strong>(用来向第1点和第2点推广,以此赚钱)</li><li><strong>一个能保存你的想法和文字的地方</strong>(用于营销、客户工作、产品规划和内容创作)</li></ol><p>我几乎试过市面上所有类型的软件。</p><p>由于我们要尽可能保持简单和低成本,如果我从零开始,以下是我会采用的方案:</p><h3 id="_1-一个能产生流量的地方" tabindex="-1">1) 一个能产生流量的地方 <a class="header-anchor" href="#_1-一个能产生流量的地方" aria-label="Permalink to &quot;1) 一个能产生流量的地方&quot;">​</a></h3><p>很多人不会喜欢听这个。</p><p>但最简单、最容易上手的产生流量的方式,就是在社交媒体上写作。</p><p>为什么?</p><ul><li>社交媒体是免费的。只要练习够多,任何人都能建立起自己的受众(没错,社交媒体是一种技能,不是运气)。</li><li>你可以每天发布内容,向社交媒体受众推广你的产品(而付费广告、赞助播客或电子报都是要花钱的)。</li><li>你可以用内容无限地测试各种想法,看哪种最能带来增长和销售。</li><li>通过写作,你不需要学视频剪辑、音频剪辑或平面设计。任何人都能写并发布一个有影响力的想法。</li></ul><p>这样,你有几个选择:</p><p>X、Threads,或LinkedIn。</p><p>选一个你最有共鸣的,把所有精力都投入到那上面。</p><p>X上有很多潜力和深刻的想法。</p><p>Threads目前对初学者来说似乎不错,但市场成熟度较低(就像Instagram一样),所以喷子相当多。</p><p>LinkedIn的钱最多,但相当无聊且偏专业化。</p><p>如果你不知道在这些平台上该写什么,下载我的<a href="https://thedankoe.com/get/idea-museum" target="_blank" rel="noreferrer">创意博物馆(Idea Museum)</a>。这是一份我作为初学者成长过程中写过的所有内容的模板合集。</p><h3 id="_2-一个能收集邮箱的地方" tabindex="-1">2) 一个能收集邮箱的地方 <a class="header-anchor" href="#_2-一个能收集邮箱的地方" aria-label="Permalink to &quot;2) 一个能收集邮箱的地方&quot;">​</a></h3><p>现在你已经在通过社交媒体产生流量了。</p><p>接下来,你需要一个能展示你能力的地方。</p><p>你需要一个可以直接向一批感兴趣的潜在客户推广你的产品或服务的地方(这才是你赚到大部分钱的地方)。</p><p>这最好通过较长篇幅的内容来实现。</p><p>(小提示:我们稍后会讲怎么写这些内容。)</p><p>换句话说,你需要一份电子报(newsletter)。</p><p>为什么?</p><p>我喜欢把一个短内容平台和一个长内容平台配对使用。</p><p>你_可以_用播客或YouTube频道来替代电子报,但这样做有几个缺点。</p><ul><li>你需要音频和视频设备。</li><li>你需要音频、视频以及大量的社交媒体技能。</li><li>你最终还是得建一份邮件列表,才能有一个能脱离社交媒体、直接与他们对话的地方。</li></ul><p>到目前为止,流程是这样的:</p><p>撰写社交媒体内容 &gt; 推广你的电子报。</p><p>我个人推荐<a href="https://thedankoe.com/get/beehiiv" target="_blank" rel="noreferrer">使用Beehiiv来建立你的邮件列表。</a></p><p>前2500名订阅者是免费的(这已经不少了),而且你还可以建网站、写博客,并设置自动化流程。</p><h3 id="_3-一个用于收款和产品-服务托管的地方" tabindex="-1">3) 一个用于收款和产品/服务托管的地方 <a class="header-anchor" href="#_3-一个用于收款和产品-服务托管的地方" aria-label="Permalink to &quot;3) 一个用于收款和产品/服务托管的地方&quot;">​</a></h3><p>现在你有了两个客户触点——社交媒体和电子报,你需要一个可以_链接过去_的地方,让他们能为产品或服务付钱给你。</p><p>而且因为我们要尽可能保持简单,你还需要一个具备落地页、数字产品托管、课程、社群功能以及教练通话预约功能的地方。</p><p>我用各种软件都折腾了个遍。</p><p>可选的太多了。</p><p>但Stan最近进入了我的视野,我已经把我自己的所有东西都搬到了他们那边。</p><p>他们以“最简单的启动网络生意方式”为自豪,用过之后,我认同这一点。</p><p><a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">这是Stan的链接。</a></p><h3 id="_4-一个保存营销和内容想法-文字的地方" tabindex="-1">4) 一个保存营销和内容想法/文字的地方 <a class="header-anchor" href="#_4-一个保存营销和内容想法-文字的地方" aria-label="Permalink to &quot;4) 一个保存营销和内容想法/文字的地方&quot;">​</a></h3><p>作为一个网络生意的经营者,你80%的工作归根结底就是_想法和写作。_</p><ul><li>营销的想法</li><li>内容的想法</li><li>电子报的想法</li><li>产品的想法</li><li>服务的想法</li><li>把这些都梳理并写出来</li></ul><p>每天留出1-2小时专门用来写内容、电子报和推广文案,这是必须的。</p><p>更进一步说,你需要一个地方来构思和撰写你的数字产品或服务内容。</p><p>有时你还需要一个地方来存放模板、客户工作表,或客户工作内容本身。</p><p>打个不要脸的广告,这也是我们打造Kortex的原因。</p><p>我们在今年年底前还会推出一些很酷的功能(比如AI综合功能——你可以选择多个文档、来源或采集内容,用AI把它们转化为摘要、大纲或笔记,省去费时的整理和记笔记工作)。</p><p><a href="https://kortex.co/" target="_blank" rel="noreferrer">在这里注册。</a> 免费版就可以让你无限制地写文档、采集无限量的想法(还能和Readwise整合,存储你所有的推文收藏和高亮)。</p><p>现在的问题是:</p><p>我要卖什么?</p><h2 id="第二步-你擅长什么" tabindex="-1">第二步)你擅长什么? <a class="header-anchor" href="#第二步-你擅长什么" aria-label="Permalink to &quot;第二步)你擅长什么?&quot;">​</a></h2><p>到目前为止,我们的生意看起来是这样的:</p><p>社交媒体内容 &gt; 收集邮箱 &gt; 发送电子报 &gt; 在社交媒体和电子报中推广你的数字产品或服务 &gt; 把所有内容都创建在Kortex里,以便集中管理。</p><p>现在我们需要确定_你要围绕什么写内容、写邮件,创建产品或服务。_</p><p>这方面我帮不了你太多,但我可以问一些能帮你找到答案的问题。</p><p>从这些问题出发,想出1个你想围绕它来打造这个生意的主要技能或兴趣。</p><ul><li>你最喜欢的实用类非虚构书籍是什么?</li><li>你现在的工作是什么/你学的是什么专业?</li><li>有没有其他人已经在网上做这些事了?如果有,那很好。</li><li>在你生活的某个领域,你实现了怎样的转变?</li><li>如果现在要你就_一个_兴趣写一篇论文,会是什么?</li></ul><p>要果断。</p><p>我们只是需要一个起点。</p><p>接下来,我希望你做几件事:</p><ul><li>写下在那个技能或兴趣领域中的5位作者、创作者或专家。</li><li>在Kortex里为他们每人保存5条名言或想法。</li><li>研究他们在卖什么数字产品(书?课程?教练服务?)</li></ul><p>这就是你获得写作素材和销售想法的地方。</p><p><img src="'+t+'" alt=""></p><p>接下来,按上面的截图操作。</p><p>把你的主要兴趣拆解成3个主要主题。</p><p>然后,把这些主题至少拆解成5个真实世界中的痛点和5个内容想法。</p><p>如果你想要完整的模板和演示讲解,<a href="https://thedankoe.com/get/opbl" target="_blank" rel="noreferrer">一人企业启动手册(One-Person Business Launchpad)</a>里有以上内容,以及更多。</p><blockquote><p>小贴士:没有人真的有原创想法。人们都是把有效的东西和其他想法结合起来,让它看起来独特。最独特的人,不过是那些从别人没有关注过、或没听说过的来源里组合想法的人。</p></blockquote><h2 id="第三步-微产品与微服务" tabindex="-1">第三步)微产品与微服务 <a class="header-anchor" href="#第三步-微产品与微服务" aria-label="Permalink to &quot;第三步)微产品与微服务&quot;">​</a></h2><p>好了,我们已经有了产生流量的方法。</p><p>我们也有了要写的技能或兴趣。</p><p>现在,我们需要把这个技能或兴趣,转化成人们愿意付钱的东西。</p><p>有两种方式可以做到:</p><h3 id="_1-微产品" tabindex="-1">1) 微产品 <a class="header-anchor" href="#_1-微产品" aria-label="Permalink to &quot;1) 微产品&quot;">​</a></h3><p>上周我和John Hu聊过。</p><p>他是Stan的CEO,一个为创作者打造的简单网店建站工具。</p><p>在创办Stan之前,他是TikTok上的一名创作者。</p><p>在成为创作者之前,他在高盛(Goldman Sachs)工作。</p><p>作为创作者,他发布内容,提供职业建议。</p><p>在几个人询问之后,他决定让人们花10美元下载一份他以前的简历(那份让他拿到高盛工作的简历)。</p><p>他没觉得这能带来多大成效,但结果很快就靠它赚了1000美元。</p><p>随着我和Stan团队合作得更多,他们提到有不少创作者都是从一个10到19美元的数字下载产品起步的。有些人靠这赚了数百万(真的),另一些人赚了数千。</p><p>经验教训:</p><p>你手头很可能已经有某个东西,可以上传到网上,标个小价格,围绕它创作内容,打造一份副业收入。</p><p>它可能就存在你硬盘的某个角落,或在你的Kortex里,又或者还困在你脑子里,等着被写成一本10页左右的小电子书或指南。</p><h3 id="_2-微服务" tabindex="-1">2) 微服务 <a class="header-anchor" href="#_2-微服务" aria-label="Permalink to &quot;2) 微服务&quot;">​</a></h3><p>之前我谈过“微报价(micro offer)”这个概念。</p><p>实际上,它就是一种微服务。</p><p>问题在于,自由职业者、教练、顾问或其他服务提供者总以为,他们必须在开始销售之前把一切都准备妥当。落地页。logo。项目的体系和教学内容。</p><p>错了。</p><p>你实际上只需要能够教授你的技能或兴趣就够了。</p><p>昨天,在Kortex高级会员社群里,有人发了一个帖子,说自己在变现这件事上感到很迷茫。</p><p>他做了十多年的程序员和系统分析师。</p><p>他开始在社交媒体上写作以建立受众群体,但感觉自己必须去卖那些细分领域自我提升回音室里其他人都在卖的东西——很多人都发现自己身处其中。</p><p>他不知道该尝试代笔写作还是效率教练,来开始赚钱。</p><p>我问他:</p><p>「你为什么不直接教别人你的技能呢?教他们编程或系统分析,作为提升技能、打开新职业机会的方式。编程这个领域非常庞大,人们不停地在购买课程和训练营,把它当作上大学的替代方案。」</p><p>他回答:</p><p>「我从来没这么想过。」</p><p>重点是,在某种技能或兴趣上,你可能已经比其他人领先1-2步了。</p><p>你可以就那件事写内容。</p><p>你可以收750-1000美元,提供一套包含4次Zoom通话的服务,把你懂的东西教给对方。</p><p>(线上私人教练一直都是这么做的。他们收费其实更高。大多数人只是害怕为自己出于好奇心免费学到的东西收钱。不是每个人都像你一样。不是每个人都想花4年慢慢积累知识。他们想要一切都直接给到手上,好实现自己的目标,因为他们是忙碌的人,把时间花在生活的其他方面。)</p><p>为什么我推荐一套4次通话?</p><ul><li>因为你现在就可以开始,不需要别的任何东西。</li><li>如果有人愿意为此付750-1000美元,你就获得了所需的验证,可以开始把它打造成更完善的项目或课程。</li><li>它给你足够的时间去教一些有分量的东西。你也可以只卖1次教练通话,但通常你需要更多时间才能把你懂的东西教明白。</li></ul><p>现在的问题是:</p><p>我要如何吸引愿意为此付钱的人?</p><h2 id="第4步-以卖点驱动的内容" tabindex="-1">第4步)以卖点驱动的内容 <a class="header-anchor" href="#第4步-以卖点驱动的内容" aria-label="Permalink to &quot;第4步)以卖点驱动的内容&quot;">​</a></h2><p>由于我们试图用<em>最易上手、成本最低的方式</em>来做这件事,这就把我们的选择缩小到了几个能吸引人为你的产品或服务付费的方法:</p><ol><li>社交媒体</li><li>写作</li></ol><p>社交媒体是免费使用的。你不需要付费投广告,不需要学SEO,也不需要付费购买播客或newsletter的赞助位。</p><p>作为额外好处,你还能<em>建立受众群体。</em>建立受众群体这件事神奇之处在于,只要你保持一致性,就能不断向越来越多的人进行再营销。</p><p>很多人是靠冷邮件和冷电话开始做线上生意的。这完全没什么问题,但为什么不直接在社交媒体上写内容,这样你就可以做暖触达,<em>同时还能让人主动来找你。</em></p><p>在所有分发方式中,社交媒体可以说是杠杆最高、最易获取、最经济实惠的建立业务的方式。</p><h3 id="选择写作主题" tabindex="-1">选择写作主题 <a class="header-anchor" href="#选择写作主题" aria-label="Permalink to &quot;选择写作主题&quot;">​</a></h3><p>在过去,我教人们在线上写作的内容要相当宽泛、跨学科。</p><p>但如果你是一个只想开始赚钱的新手,我仍然推荐这样做,不过有一条更快的变现路径。</p><p>首先,拿出你产品或服务的<em>主题</em>,把它拆分成:</p><ol><li>你的个人故事。你在相关主题上的过去、中间过程和现在。</li><li>人们面临的痛点。你写的80%的内容都会从这里开始。</li><li>已经表现良好的内容主题。在YouTube上搜索你的主题,记下表现最好的视频。观看它们获取内容灵感。</li></ol><p>就这样。</p><p>新建一个文档或笔记,针对每一项写下5-10个要点。</p><p>一旦开始了,你再去操心该如何写作和构建内容结构。</p><p>现在,<em>就当你在给一个朋友发短信,他们在向你提问关于你感兴趣主题的问题。把你的答案公开写在社交媒体上。</em></p><h3 id="从newsletter和帖子的框架开始" tabindex="-1">从Newsletter和帖子的框架开始 <a class="header-anchor" href="#从newsletter和帖子的框架开始" aria-label="Permalink to &quot;从Newsletter和帖子的框架开始&quot;">​</a></h3><p>我学会写内容的方法是,模仿我喜欢的写作方式,把自己的想法套进去。</p><p>你不是简单地照抄一个想法然后改几个词。</p><p><em>你要研究你想模仿的内容的</em><em><strong>结构</strong></em><em>。</em></p><p>你把这个结构写下来,然后试着把自己的想法套进去。</p><p>在Newsletter写作方面,我喜欢的一个结构是P&amp;P框架(<a href="https://app.kortex.co/public/document/bec7fcec-d76c-4d00-8669-37f53892fead" target="_blank" rel="noreferrer">这里是一个资源</a>)。</p><p>Pain and process(痛点与过程)。</p><p>很简单……你选一个主题。你在开头描绘一个与该主题相关的痛点。然后,你分步拆解一个克服这个痛点的过程(和你正在读的这篇newsletter的结构相当接近)。</p><p>先列大纲,然后再写。</p><p>对于帖子,做同样的事情。</p><p>刷社交媒体,把10篇优秀帖子的链接嵌入到一个Kortex文档里。</p><p>在每一篇下面,逐行拆解它的结构。</p><p>然后,把你自己的主题和想法套进这些结构里,用你自己的声音写出来。</p><h2 id="第5步-老天啊-请务必推广你自己" tabindex="-1">第5步)老天啊,请务必推广你自己 <a class="header-anchor" href="#第5步-老天啊-请务必推广你自己" aria-label="Permalink to &quot;第5步)老天啊,请务必推广你自己&quot;">​</a></h2><p>我做这件事已经有一段时间了。</p><p>人们赚不到钱的<em>唯一</em>原因,就是他们不推广自己。</p><p>你没看错。</p><p>是的,即便你是在向零粉丝、零读者推广。</p><p>为什么?</p><p>如果你不推广你的产品或服务:</p><p><strong>1)你没有动力去提升自己的写作。</strong></p><p>当<em>你看不到写作来建立受众群体的意义时</em>,放弃就容易多了。</p><p>如果你没<em>看到</em>一条赚钱的路径(你的产品或服务链接在你的文章里),那你就不会去尝试赚钱,你会觉得这一切毫无意义。</p><p>我在140个粉丝的时候写了我的第一本电子书,到500个粉丝的时候赚了3000美元。这之所以发生,是因为我想让它发生,并尽力为我的产品争取尽可能多的流量。</p><p><strong>2)人们不会知道他们可以付钱给你。</strong></p><p>即使已经关注我多年,我仍然会有人告诉我,他们根本不知道我有可以付费购买的产品。</p><p>而我还以为自己在推广上做得挺不错的。</p><p>事实是,如果你只是指望别人自己<em>找到</em>你卖的东西,你会破产的。</p><p>你需要把它摆到他们面前,告诉他们这东西能怎么帮到他们。</p><p><strong>3)你永远也克服不了对销售的恐惧。</strong></p><p>网上有一小部分喜欢发声的少数人。</p><p>那1%的人厌恶广告和自我推广(尽管他们声称支持独立创作者)。</p><p>他们宁愿你去乞求捐款或赞助,也不愿你创造自己的产品并向他们推销。</p><p>无视这些人。</p><p>你会在帖子的评论区看到他们,然后以为没人会买那个人的产品。我可以告诉你,每收到1条负面评论,就有50-100人买了我的产品。他们只是什么都不说,因为他们不是傻子。</p><p><strong>4)不存在的东西是无法改进的。</strong></p><p>如果你从来不推广你的产品或服务,你要怎么在营销和销售上变得更好?</p><p><em>你没有任何</em><em><strong>数据</strong></em><em>可供改进。</em></p><p>这在商业、写作,或任何其他项目或技能上都是一样的。</p><p>你一开始会很烂。</p><p>然后你会变好。</p><p>但如果你一开始不烂,你就不会变好。</p><p>所以,在结束这篇文章之前,我完全允许你去烂一把。</p><p>除了我在这篇文章里给你的建议,你不需要别的任何东西。</p><p>第一个成功的生意——那个没有任何人教他们该怎么做的人——就是自己琢磨出来的。</p><p>试错。</p><ul><li>每天回复你自己的一条帖子。轮流推广你的newsletter订阅入口和你的产品或服务。</li><li>在你的每周邮件里,推广一个通往你产品或服务的链接。</li><li>现在你要做的就是专注于提升写作,持续为你的newsletter注入内容。</li></ul><p>去吧。</p><p>——Dan</p><hr><p><a href="/en/letters/the-simplest-way-to-start-a-one-person-business-micro-products">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',200))])}const P=r(d,[["render",m]]);export{q as __pageData,P as default};
